(3665, 'Lalit Kumar', 37, 'C++', 'What are classes and objects in C++? ', 'Not Answered', 'A class is like a blueprint of an object. It is a user-defined data type with data members and member functions and is defined with the keyword class.', NULL, 2, 3111),
(3666, 'Lalit Kumar', 37, 'C++', 'What are access modifiers? ', 'Not Answered', 'You use access modifiers to define accessibility for the class members. It defines how to access the members of the class outside the class scope.', NULL, 2, 3111),
(3667, 'Lalit Kumar', 37, 'C++', 'Difference between equal to (==) and assignment operator(=)?', 'Not Answered', ' The equal to operator == checks whether two values are equal or not. If equal, then it’s true; otherwise, it will return false.', NULL, 2, 3111),
(3668, 'Lalit Kumar', 37, 'C++', 'Can you compile a program without the main function? ', 'Not Answered', 'Yes, you can compile a program without the main function, but you cannot run or execute the program because the main() function is the entry point, from where all the execution begins. And without the entry point, then you can execute the program.', NULL, 2, 3111),
(3669, 'Lalit Kumar', 37, 'C++', 'When is void() return type used?', 'Not Answered', 'You use the void() return type when you don’t want to return any value. It specifies that the function doesn’t return a value.', NULL, 2, 3111),
