INSERT INTO `question` (`Q.ID`, `E.ID`, `Ques`, `Opt1`, `Opt2`, `Opt3`, `Opt4`, `Corr`, `Marks`, `status`) VALUES
(5003, 16, 'Who invented Java Programming?', 'a)Guido van Rossum', 'b) James Gosling', 'c) Dennis Ritchie', 'd) Mark Zukerberg', '2', 1, 1),
(5004, 16, ' Which statement is true about Java?  ', 'a) Java is a sequence-dependent programming language ', 'b) Java is a code dependent programming language ', 'c) Java is a platform-dependent programming language ', 'd) Java is a platform-independent programming language', ' 4', 1, 1),
(5005, 16, 'Which component is used to compile, debug and execute the java programs? ', 'a) JRE ', 'b) JIT ', 'c) JDK ', 'd) JVM', ' 3', 1, 1),
(5006, 16, 'Which one of the following is not a Java feature? ', 'a) Object-oriented ', 'b) Use of pointers ', 'c) Portable ', 'd) Dynamic and Extensible', ' 2', 1, 1),
(5007, 16, 'Which of these cannot be used for a variable name in Java? ', 'a) identifier & keyword ', 'b) identifier ', 'c) keyword ', 'd) none of the mentioned', ' 3', 1, 1),
(5008, 17, 'Which of these best describes an array? ', 'a) A data structure that shows a hierarchical behavior ', 'b) Container of objects of similar types ', 'c) Arrays are immutable once initialised ', 'd) Array is not a data structure', ' 2', 1, 1),
(5009, 17, 'Process of removing an element from stack is called __________ ', 'a) Create ', 'b) Push ', 'c) Evaluation ', 'd) Pop', ' 4', 1, 1),
(5010, 17, 'The data structure required for Breadth First Traversal on a graph is? ', 'a) Stack ', 'b) Array ', 'c) Queue ', 'd) Tree', ' 3', 1, 1),
(5011, 17, ' A linear collection of data elements where the linear node is given by means of pointer is called? ', 'a) Linked list ', 'b) Node list ', 'c) Primitive list ', 'd) Unordered list', ' 1', 1, 1),
(5012, 17, 'Which of the following is false about a doubly linked list? ', 'a) We can navigate in both the directions ', 'b) It requires more space than a singly linked list ', 'c) The insertion and deletion of a node take a bit longer ', 'd) Implementing a doubly linked list is easier than singly linked list', ' 4', 1, 1),
(5013, 18, 'Who invented C++? ', 'a) Dennis Ritchie ', 'b) Ken Thompson ', 'c) Brian Kernighan ', 'd) Bjarne Stroustrup', ' 1', 1, 1),
(5014, 18, 'What is C++? ', 'a) C++ is an object oriented programming language ', 'b) C++ is a procedural programming language ', 'c) C++ supports both procedural and object oriented programming language ', 'd) C++ is a functional programming language', ' 3', 1, 1),
(5015, 18, 'Which of the following is the correct syntax of including a user defined header files in C++? ', 'a) #include [userdefined] ', 'b) #include “userdefined” ', 'c) #include <userdefined.h> ', 'd) #include <userdefined>', ' 2', 1, 1),
(5016, 18, 'Which of the following is used for comments in C++? ', 'a) /* comment */ ', 'b) // comment */ ', 'c) // comment ', 'd) both // comment or /* comment */', ' 4', 1, 1),
(5017, 18, ' Which of the following user-defined header file extension used in c++? ', 'a) hg ', 'b) cpp ', 'c) h ', 'd) hf', ' 3', 1, 1),
(5018, 19, ' What is an operating system? ', 'a) interface between the hardware and application programs ', 'b) collection of programs that manages hardware resources ', 'c) system service provider to the application programs ', 'd) all of the mentioned', ' 4', 1, 1),
(5019, 19, 'What is the main function of the command interpreter? ', 'a) to provide the interface between the API and application program ', 'b) to handle the files in the operating system ', 'c) to get and execute the next user-specified command ', 'd) none of the mentioned', ' 3', 1, 1),
(5020, 19, 'In Operating Systems, which of the following is/are CPU scheduling algorithms? ', 'a) Priority ', 'b) Round Robin ', 'c) Shortest Job First ', 'd) All of the mentioned', ' 4', 1, 1),
(5021, 19, 'To access the services of the operating system, the interface is provided by the ___________ ', 'a) Library ', 'b) System calls ', 'c) Assembly instructions ', 'd) API', ' 2', 1, 1),
(5022, 19, 'CPU scheduling is the basis of ___________ ', 'a) multiprogramming operating systems ', 'b) larger memory sized systems ', 'c) multiprocessor systems ', 'd) none of the mentioned', ' 3', 1, 1);
INSERT INTO `question1` (`Q.ID`, `E.ID`, `Ques`, `Ans`, `Marks`) VALUES
(1, 16, 'What do you mean by Java?', 'Java is Object-Oriented programming language.', 2),
(2, 16, 'What is the feature of Java?', 'OOP,Robust', 1),
(4, 16, 'Which feature of OOP is implemented by Class?', 'Encapsulation', 1),
(5, 16, ' What is the extension of compiled java classes?', '.class', 1),
(6, 16, ' What is the numerical range of a char data type in Java?', ' 0 to 65535', 1),
(7, 16, ' Which class provides system independent server side implementation?', 'Server Socket', 1),
(8, 16, ' What is the difference between an Inner Class and a Sub-Class?', 'An Inner class is a class which is nested within another class,whereas a sub-class is a class which inherits from another class', 2),
(9, 16, ' What are the various access specifiers for Java classes?', 'Public,Private,Protected', 2),
(10, 16, 'What’s the purpose of Static methods and static variables?', 'to make a method or variable shared for all objects.', 2),
(12, 16, ' What is data encapsulation?', 'Encapsulation is a concept in Object Oriented Programming for combining properties and methods in a single unit', 2),
(13, 17, 'What is the value of the postfix expression 6 3 2 4 + – *?', '-18', 1),
(14, 17, 'The concatenation of two lists can be performed in O(1) time. Which of the following variation of the linked list can be used?', 'Circular doubly Linked list', 1),
(15, 17, 'Which is the predefined method available in Java to convert decimal to binary numbers?', 'toBinaryString(int)', 1),
(16, 17, 'While evaluating a prefix expression, the string is read from?', 'right to left', 1),
(17, 17, ' Which of the following application makes use of a circular linked list?', 'Allocating CPU to resources', 1),
(18, 17, 'What do you mean by a Data structure?', 'Data structure is a format for storing data in a structured manner', 2),
(19, 17, 'What are some of the applications of DS?', ' For representing a city region telephone network.', 2),
(20, 17, ' What are the advantages of a Linked list over an array?', 'each node is connected using link, it is not necessary that memory has to be contiguous.', 2),
(21, 17, 'What is the difference between an Array and Stack?', 'Size of the stack keeps on changing whereas size of the array is fixed', 2),
(22, 17, 'When can you tell that a Memory Leak will occur?    ', 'A memory leak occurs when a program does not free a block of memory allocated dynamically.', 2),
(23, 18, 'Which approach is used by C++ to solve a problem?', 'Bottom-Up', 1),
(24, 18, 'By default, all the files in C++ are opened in _________ mode.', 'Text', 1),
(25, 18, ' What is the size of wchar_t in C++?', 'Based on number of bits', 1),
(26, 18, '. What is Inheritance in C++?', ' Deriving new classes from existing classes', 1),
(27, 18, 'Which symbol is used to declare the preprocessor directives in C++?', '#', 1),
(28, 18, 'What are classes and objects in C++? ', 'A class is like a blueprint of an object. It is a user-defined data type with data members and member functions and is defined with the keyword class.', 2),
(29, 18, 'What are access modifiers? ', 'You use access modifiers to define accessibility for the class members. It defines how to access the members of the class outside the class scope.', 2),
(30, 18, 'Difference between equal to (==) and assignment operator(=)?', ' The equal to operator == checks whether two values are equal or not. If equal, then it’s true; otherwise, it will return false.', 2),
(31, 18, 'Can you compile a program without the main function? ', 'Yes, you can compile a program without the main function, but you cannot run or execute the program because the main() function is the entry point, from where all the execution begins. And without the entry point, then you can execute the program.', 2),
(32, 18, 'When is void() return type used?', 'You use the void() return type when you don’t want to return any value. It specifies that the function doesn’t return a value.', 2),
(33, 19, 'In a timeshare operating system, when the time slot assigned to a process is completed, the process switches from the current state to?', 'Ready State', 1),
(34, 19, ' The main memory accommodates ____________', 'Operating System', 1),
(35, 19, ' The FCFS algorithm is particularly troublesome for ____________', 'Time Sharing', 1),
(36, 19, ' A deadlock avoidance algorithm dynamically examines the __________ to ensure that a circular wait condition can never exist.', 'Resource allocation state', 1),
(37, 19, 'Swapping _______ be done when a process has pending I/O, or has to execute I/O operations only into operating system buffers.', 'must never', 1),
(38, 19, 'Why is the operating system important?', 'It enables an interface or acts like a link for interaction between computer software that is installed on OS and users.', 2),
(39, 19, 'What is main purpose of OS?', 'The main purpose of an OS is to execute user programs and make it easier for users to understand and interact with computers', 2),
(40, 19, 'What are the benefits of a multiprocessor system?', 'A Multiprocessor system is a type of system that includes two or more CPUs. ', 2),
(41, 19, 'What is GUI?', ' GUI (Graphical User Interface) is basically a type of user interface that allows users to use graphics to interact with OS', 2),
(42, 19, 'What is Main Memory?', 'Main memory in a computer is RAM (Random Access Memory). It is also known as primary memory or read-write memory or internal memory.', 2);
